import { describe, expect, it } from 'vitest';
import { eventMetaView } from './Solution';

/**
 * 断言由 gen.py 里同一个 Python 模型生成，不手抄 ——
 * react-vitest 题的判分事实来源就是这份文件，抄错一次就永久错一次。
 * 契约型用例断言到**消息**：只写 .toThrow() 会让几条"都该抛错"的用例收敛成同一条。
 */
describe('eventMetaView：埋点元数据状态语义', () => {
  it("基线：已验收的自定义事件 ⇒ 可分析，且进\"一般事件列表\"", () => {
    expect(eventMetaView({"eventName": "pay_success", "status": "accepted", "source": "custom", "analysisKind": "none", "canManage": true, "autoTracking": false})).toEqual({"state": "live", "label": "可分析", "tone": "ok", "action": "view", "tooltip": "事件 pay_success：可分析", "governanceBucket": "live", "countsInAcceptedList": true});
  });
  it("预置事件即使还处于 pending 也不进验收队列（上报时机由系统统一配置）", () => {
    expect(eventMetaView({"eventName": "$page_start", "status": "pending", "source": "preset", "analysisKind": "none", "canManage": true, "autoTracking": false})).toEqual({"state": "preset", "label": "预置事件", "tone": "info", "action": null, "tooltip": "事件 $page_start：预置事件", "governanceBucket": "preset-owned", "countsInAcceptedList": true});
  });
  it("待验收 + 有\"可管理\"权限 ⇒ 渲染成可点的验收动作", () => {
    expect(eventMetaView({"eventName": "new_checkout", "status": "pending", "source": "custom", "analysisKind": "none", "canManage": true, "autoTracking": false})).toEqual({"state": "needs-accept", "label": "待验收 · 可验收", "tone": "warn", "action": "accept", "tooltip": "事件 new_checkout：待验收 · 可验收", "governanceBucket": "pending-acceptance", "countsInAcceptedList": false});
  });
  it("待验收 + 无权限 ⇒ 只读（官方口径：\"无权限只能看\"）", () => {
    expect(eventMetaView({"eventName": "new_checkout", "status": "pending", "source": "custom", "analysisKind": "none", "canManage": false, "autoTracking": false})).toEqual({"state": "pending-locked", "label": "待验收 · 只读", "tone": "muted", "action": null, "tooltip": "事件 new_checkout：待验收 · 只读", "governanceBucket": "pending-acceptance", "countsInAcceptedList": false});
  });
  it("边界：已验收但分析类型是热力图、全埋点未开 ⇒ 能力缺口，不算验收问题", () => {
    expect(eventMetaView({"eventName": "banner_heat", "status": "accepted", "source": "custom", "analysisKind": "heatmap", "canManage": true, "autoTracking": false})).toEqual({"state": "capability-gap", "label": "需开启全埋点", "tone": "warn", "action": null, "tooltip": "事件 banner_heat：需开启全埋点", "governanceBucket": "capability-gap", "countsInAcceptedList": true});
  });
  it("边界：被禁用的预置事件 ⇒ disabled 优先于 preset", () => {
    expect(eventMetaView({"eventName": "$AppClick", "status": "disabled", "source": "preset", "analysisKind": "none", "canManage": true, "autoTracking": false})).toEqual({"state": "disabled", "label": "已禁用 · 停止上报", "tone": "danger", "action": "re-enable", "tooltip": "事件 $AppClick：已禁用 · 停止上报", "governanceBucket": "stopped", "countsInAcceptedList": false});
  });
  it("退化：草稿态不给任何\"可分析\"承诺", () => {
    expect(eventMetaView({"eventName": "wip_event", "status": "draft", "source": "custom", "analysisKind": "none", "canManage": false, "autoTracking": false})).toEqual({"state": "draft", "label": "草稿 · 未提交", "tone": "muted", "action": null, "tooltip": "事件 wip_event：草稿 · 未提交", "governanceBucket": "draft", "countsInAcceptedList": false});
  });
  it("边界：验收未通过 ⇒ danger 但不进\"停止采集\"桶", () => {
    expect(eventMetaView({"eventName": "bad_event", "status": "rejected", "source": "custom", "analysisKind": "none", "canManage": true, "autoTracking": false})).toEqual({"state": "rejected", "label": "验收未通过", "tone": "danger", "action": "revise", "tooltip": "事件 bad_event：验收未通过", "governanceBucket": "rejected", "countsInAcceptedList": false});
  });
  it("非法：整行是 null", () => {
    expect(() => eventMetaView(null)).toThrow("row must be an object");
  });
  it("非法：未知事件状态", () => {
    expect(() => eventMetaView({"eventName": "x", "status": "archived", "source": "custom", "analysisKind": "none", "canManage": true, "autoTracking": false})).toThrow("unknown event status");
  });
  it("非法：未知事件来源（预置与自定义之外没有第三种）", () => {
    expect(() => eventMetaView({"eventName": "x", "status": "accepted", "source": "imported", "analysisKind": "none", "canManage": true, "autoTracking": false})).toThrow("unknown event source");
  });
  it("非法：未知分析类型（它决定要不要全埋点，不许猜）", () => {
    expect(() => eventMetaView({"eventName": "x", "status": "accepted", "source": "custom", "analysisKind": "funnel", "canManage": true, "autoTracking": false})).toThrow("unknown analysis kind");
  });
});

